import React from "react";
import "./Gallery.css";

const galleryItems = [
{ title: "Home Cleaning" },
{ title: "Gardening" },
{ title: "Plumbing Work" },
{ title: "Electrical Work" },
{ title: "Painting Work" },
{ title: "Carpenter Work" },
{ title: "Beauty & Makeup" },
{ title: "Massage Therapy" },
{ title: "AC Repair" },
{ title: "Pest Control" },
{ title: "Pet Care" },
{ title: "Laptop Repair" }
];

export default function Gallery() {
return ( <div className="gallery-container"> <h2 className="gallery-title">Gallery</h2> <div className="gallery-grid">
{galleryItems.map((item, index) => ( <div className="gallery-card" key={index}> <div className="gallery-placeholder"></div> <p>{item.title}</p> </div>
))} </div> </div>
);
}
